import{_ as e,o as l,c as a,a3 as n}from"./chunks/framework.bvEHUNtb.js";const x=JSON.parse('{"title":"C-07 律数初探","description":"深入三分损益法、朱载堉十二平均律与传统律制的数学结构及世界声学史位置。","frontmatter":{"title":"C-07 律数初探","description":"深入三分损益法、朱载堉十二平均律与传统律制的数学结构及世界声学史位置。","category":"guide","outline":"deep","aliases":["律数初探","三分损益法","十二平均律"]},"headers":[],"relativePath":"topics/traditional-wisdom/common-knowledge/temperament-mathematics.md","filePath":"topics/traditional-wisdom/common-knowledge/temperament-mathematics.md","lastUpdated":1786982540000}'),s={name:"topics/traditional-wisdom/common-knowledge/temperament-mathematics.md"};function r(d,t,i,o,g,p){return l(),a("div",null,[...t[0]||(t[0]=[n(`<h1 id="c-07-·-律数初探-音律中的数学结构" tabindex="-1">C-07 · 律数初探：音律中的数学结构 <a class="header-anchor" href="#c-07-·-律数初探-音律中的数学结构" aria-label="Permalink to &quot;C-07 · 律数初探：音律中的数学结构&quot;">​</a></h1><h2 id="三分损益法完整数学推导-·-朱载堉十二平均律-·-世界声学史坐标" tabindex="-1">三分损益法完整数学推导 · 朱载堉十二平均律 · 世界声学史坐标 <a class="header-anchor" href="#三分损益法完整数学推导-·-朱载堉十二平均律-·-世界声学史坐标" aria-label="Permalink to &quot;三分损益法完整数学推导 · 朱载堉十二平均律 · 世界声学史坐标&quot;">​</a></h2><p><strong>系列：</strong> 中华传统智慧体系 · 通识基础知识库 · 文化通识篇（C系列）· 礼制度数组<br><strong>版本：</strong> v1.0（2026年8月）<br><strong>前置篇目（必读）：</strong> 18·五音十二律（本篇为其深化扩展篇）<br><strong>后续篇目：</strong> 纳音五行（后续；本篇数学结构的直接应用出口）<br><strong>平行篇目：</strong> C-06·岁时节令体系</p><hr><h2 id="写在前面-这篇讲什么" tabindex="-1">写在前面：这篇讲什么？ <a class="header-anchor" href="#写在前面-这篇讲什么" aria-label="Permalink to &quot;写在前面：这篇讲什么？&quot;">​</a></h2><p>主干第18篇（五音六律）已经建立了完整的概念框架：<br> 五音是什么、十二律是什么、三分损益法的基本原理、<br> 以及&quot;12律 × 5音 = 60&quot;这一通向纳音五行的核心数学结构。</p><p><strong>本篇（C-07）是主干18的深化扩展篇，专注于三件事：</strong></p><ol><li><strong>三分损益法的完整数学推导</strong><br> 从黄钟出发，逐步推算全部十二律，<br> 展示每一步的数学操作与音律逻辑，<br> 并正面处理&quot;黄钟不能还原&quot;这一历史难题。</li><li><strong>朱载堉与十二平均律</strong><br> 明代王子朱载堉如何用一把算盘，<br> 在没有计算机的时代，<br> 精确计算出 $$ \\sqrt[12]{2} $$，<br> 从数学上彻底解决了两千年的律学难题。</li><li><strong>世界声学史的坐标定位</strong><br> 客观呈现朱载堉的成就在世界声学史上的位置，<br> 以及与西方同期研究的时间关系——<br> 不夸大，不回避，只做如实陈述。</li></ol><p><strong>本篇不重复主干18已有内容，如需五音·十二律的概念基础，请先阅读主干18·五音六律。</strong></p><hr><h2 id="一、问题的起点-黄钟为什么-不能还原" tabindex="-1">一、问题的起点：黄钟为什么&quot;不能还原&quot;？ <a class="header-anchor" href="#一、问题的起点-黄钟为什么-不能还原" aria-label="Permalink to &quot;一、问题的起点：黄钟为什么&quot;不能还原&quot;？&quot;">​</a></h2><h3 id="_1-1-三分损益法的数学本质" tabindex="-1">1.1 三分损益法的数学本质 <a class="header-anchor" href="#_1-1-三分损益法的数学本质" aria-label="Permalink to &quot;1.1 三分损益法的数学本质&quot;">​</a></h3><p>三分损益法，本质上是一套<strong>纯五度相生律</strong>：</p><ul><li>三分损一（×2/3）：音高上升一个纯五度</li><li>三分益一（×4/3）：音高下降一个纯四度</li></ul><p>用现代数学语言表达：</p><ul><li>纯五度的频率比 = $$ \\frac{3}{2} $$</li><li>纯四度的频率比 = $$ \\frac{4}{3} $$</li></ul><p>从黄钟出发，经过12次纯五度相生，理论上应该回到黄钟（高七个八度）。</p><h3 id="_1-2-为什么回不去" tabindex="-1">1.2 为什么回不去？ <a class="header-anchor" href="#_1-2-为什么回不去" aria-label="Permalink to &quot;1.2 为什么回不去？&quot;">​</a></h3><p>12次纯五度相生后的频率比：</p><p>$ \\left(\\frac{3}{2}\\right)^{12} = \\frac{531441}{4096} \\approx 129.746 $</p><p>7个八度的频率比：</p><p>$ 2^7 = 128 $</p><p>两者之差：</p><p>$ \\frac{531441}{524288} \\approx 1.01364 $</p><p>这个微小的差值，就是著名的&quot;毕达哥拉斯音差&quot;（Pythagorean comma）。</p><p>【原典】《汉书·律历志》<br> 【原文】&quot;推本五声，以正六律……竟不能合，此律吕之所以难精也。&quot;<br> 【版本】东汉·班固撰，中华书局点校本</p><p>班固在《汉书》中已经明确指出：<br><strong>十二律推算到最后，&quot;竟不能合&quot;——这是律学最难精通之处。</strong><br> 这个问题，先人早已发现，并持续探索了近两千年。</p><h2 id="二、三分损益法-完整数学推导" tabindex="-1">二、三分损益法：完整数学推导 <a class="header-anchor" href="#二、三分损益法-完整数学推导" aria-label="Permalink to &quot;二、三分损益法：完整数学推导&quot;">​</a></h2><h3 id="_2-1-推算基准" tabindex="-1">2.1 推算基准 <a class="header-anchor" href="#_2-1-推算基准" aria-label="Permalink to &quot;2.1 推算基准&quot;">​</a></h3><p>古人设黄钟律管长度为 <strong>81</strong>（取 $$ 9 \\times 9 = 81 $$，九为阳数之极）。</p><p>【原典】《管子·地员篇》<br> 【原文】凡将起五音，凡首，先主一而三之，四开以合九九，以是生黄钟小素之首，以成宫。<br> 【版本】战国·管仲撰（存疑，今本为后人整理）</p><p>&quot;四开以合九九&quot;——四次三倍，得 $$ 3^4 = 81 $$ 黄钟基准长度 = 81，这是三分损益法的起算点 $</p><h3 id="_2-2-完整推算过程" tabindex="-1">2.2 完整推算过程 <a class="header-anchor" href="#_2-2-完整推算过程" aria-label="Permalink to &quot;2.2 完整推算过程&quot;">​</a></h3><p><strong>操作规则：</strong></p><ul><li><strong>三分损一（下生）：</strong> 管长 × $$ \\frac{2}{3} $$，音高升高（约纯五度）</li><li><strong>三分益一（上生）：</strong> 管长 × $$ \\frac{4}{3} $$，音高降低（约纯四度）</li></ul><table tabindex="0"><thead><tr><th style="text-align:left;">步骤</th><th style="text-align:left;">操作</th><th style="text-align:left;">律名</th><th style="text-align:left;">管长 (分数)</th><th style="text-align:left;">管长 (小数)</th><th style="text-align:left;">阴阳</th><th style="text-align:left;">月份</th></tr></thead><tbody><tr><td style="text-align:left;">起点</td><td style="text-align:left;">—</td><td style="text-align:left;"><strong>黄钟</strong></td><td style="text-align:left;">81</td><td style="text-align:left;">81.000</td><td style="text-align:left;">阳律</td><td style="text-align:left;">十一月</td></tr><tr><td style="text-align:left;">1</td><td style="text-align:left;">×2/3（损）</td><td style="text-align:left;"><strong>林钟</strong></td><td style="text-align:left;">54</td><td style="text-align:left;">54.000</td><td style="text-align:left;">阴吕</td><td style="text-align:left;">六月</td></tr><tr><td style="text-align:left;">2</td><td style="text-align:left;">×4/3（益）</td><td style="text-align:left;"><strong>太簇</strong></td><td style="text-align:left;">72</td><td style="text-align:left;">72.000</td><td style="text-align:left;">阳律</td><td style="text-align:left;">正月</td></tr><tr><td style="text-align:left;">3</td><td style="text-align:left;">×2/3（损）</td><td style="text-align:left;"><strong>南吕</strong></td><td style="text-align:left;">48</td><td style="text-align:left;">48.000</td><td style="text-align:left;">阴吕</td><td style="text-align:left;">八月</td></tr><tr><td style="text-align:left;">4</td><td style="text-align:left;">×4/3（益）</td><td style="text-align:left;"><strong>姑洗</strong></td><td style="text-align:left;">64</td><td style="text-align:left;">64.000</td><td style="text-align:left;">阳律</td><td style="text-align:left;">三月</td></tr><tr><td style="text-align:left;">5</td><td style="text-align:left;">×2/3（损）</td><td style="text-align:left;"><strong>应钟</strong></td><td style="text-align:left;">128/3</td><td style="text-align:left;">42.667</td><td style="text-align:left;">阴吕</td><td style="text-align:left;">十月</td></tr><tr><td style="text-align:left;">6</td><td style="text-align:left;">×4/3（益）</td><td style="text-align:left;"><strong>蕤宾</strong></td><td style="text-align:left;">512/9</td><td style="text-align:left;">56.889</td><td style="text-align:left;">阳律</td><td style="text-align:left;">五月</td></tr><tr><td style="text-align:left;">7</td><td style="text-align:left;">×4/3（益）⚠️</td><td style="text-align:left;"><strong>大吕</strong></td><td style="text-align:left;">2048/27</td><td style="text-align:left;">75.852</td><td style="text-align:left;">阴吕</td><td style="text-align:left;">十二月</td></tr><tr><td style="text-align:left;">8</td><td style="text-align:left;">×2/3（损）</td><td style="text-align:left;"><strong>夷则</strong></td><td style="text-align:left;">4096/81</td><td style="text-align:left;">50.568</td><td style="text-align:left;">阳律</td><td style="text-align:left;">七月</td></tr><tr><td style="text-align:left;">9</td><td style="text-align:left;">×4/3（益）</td><td style="text-align:left;"><strong>夹钟</strong></td><td style="text-align:left;">16384/243</td><td style="text-align:left;">67.424</td><td style="text-align:left;">阴吕</td><td style="text-align:left;">二月</td></tr><tr><td style="text-align:left;">10</td><td style="text-align:left;">×2/3（损）</td><td style="text-align:left;"><strong>无射</strong></td><td style="text-align:left;">32768/729</td><td style="text-align:left;">44.949</td><td style="text-align:left;">阳律</td><td style="text-align:left;">九月</td></tr><tr><td style="text-align:left;">11</td><td style="text-align:left;">×4/3（益）</td><td style="text-align:left;"><strong>仲吕</strong></td><td style="text-align:left;">131072/2187</td><td style="text-align:left;">59.932</td><td style="text-align:left;">阴吕</td><td style="text-align:left;">四月</td></tr></tbody></table><p>⚠️ <strong>第7步说明（蕤宾→大吕）：</strong><br> 蕤宾位于五月（夏至），是阴阳转折点。<br> 此处连续两次&quot;益&quot;（上生），而非按常规&quot;损益交替&quot;进行。<br> 这是三分损益法中历代争议最大的节点，<br> 《汉书·律历志》与《淮南子·天文训》处理方式略有不同。<br> 本表按《汉书》通行算法呈现。</p><h3 id="_2-3-黄钟不能还原-数字的诚实" tabindex="-1">2.3 黄钟不能还原：数字的诚实 <a class="header-anchor" href="#_2-3-黄钟不能还原-数字的诚实" aria-label="Permalink to &quot;2.3 黄钟不能还原：数字的诚实&quot;">​</a></h3><p>按三分损益法，仲吕（第12律）之后，<br> 理论上应&quot;再损一&quot;回到黄钟：</p><p>$ \\frac{131072}{2187} \\times \\frac{2}{3} = \\frac{262144}{6561} \\approx 39.953 $</p><p>而黄钟原长 81 的一半（低八度）= <strong>40.500</strong></p><p>差值：$$ 40.500 - 39.953 = 0.547 $$</p><p>**这就是&quot;黄钟不能还原&quot;——<br> **<strong>按三分损益法推算十二律后，第十三律与黄钟之间存在无法消除的数学误差。</strong></p><p>先人没有回避这个问题。<br> 从汉代班固到南朝何承天，历代乐律学家提出了各种&quot;救弊&quot;方案，但都是局部修补，无法从根本上解决。</p><p>这个问题，等待了近两千年，直到一位明代王子的出现。</p><h2 id="三、朱载堉与十二平均律" tabindex="-1">三、朱载堉与十二平均律 <a class="header-anchor" href="#三、朱载堉与十二平均律" aria-label="Permalink to &quot;三、朱载堉与十二平均律&quot;">​</a></h2><h3 id="_3-1-人物-一位选择放弃王位的王子" tabindex="-1">3.1 人物：一位选择放弃王位的王子 <a class="header-anchor" href="#_3-1-人物-一位选择放弃王位的王子" aria-label="Permalink to &quot;3.1 人物：一位选择放弃王位的王子&quot;">​</a></h3><p>【原典】《明史·乐志》<br> 【原文】载堉，郑恭王厚烷之世子也……厚烷以直谏得罪，系高墙者十九年。载堉笃孝，筑土室于宫门外，席藁独处者亦十九年……厚烷卒，载堉当袭封，固辞不受，乞以爵位让其从弟……专精律历之学。<br> 【版本】清·张廷玉等撰，中华书局点校本（二十四史）</p><p>朱载堉（1536—1611年），明代郑王世子。<br> 父亲朱厚烷因直谏被囚禁高墙十九年，朱载堉在宫门外搭草棚，席地独居十九年，以示陪伴。 父亲去世后，他本可继承郡王爵位，却<strong>七次上书，坚决辞让</strong>，将王位让给堂弟，自此专心于律历之学。</p><p>**一个选择放弃王位、用一生研究音律数学的人。**这是理解朱载堉成就的人物背景。</p><h3 id="_3-2-成就-用算盘算出-sqrt-12-2" tabindex="-1">3.2 成就：用算盘算出 $$ \\sqrt[12]{2} $$ <a class="header-anchor" href="#_3-2-成就-用算盘算出-sqrt-12-2" aria-label="Permalink to &quot;3.2 成就：用算盘算出 $$ \\sqrt[12]{2} $$&quot;">​</a></h3><p>【原典】朱载堉《律学新说》（1584年）<br> 【原文】创立新法：置一尺为实，以密率除之，凡十二遍，各得其数。<br> 【版本】明·朱载堉撰，万历十二年（1584年）刊本</p><p>朱载堉的核心思想，用一句话表达：</p><p><strong>将一个八度（频率比2:1）精确等分为十二份，<br> ****每个半音的频率比 = $</strong>$ \\sqrt[12]{2} $<strong>$</strong></p><p>这就是<strong>十二平均律</strong>（朱载堉自称&quot;新法密率&quot;）。</p><p>用现代数学表达：</p><p>$ \\text{每个半音频率比} = 2^{\\frac{1}{12}} \\approx 1.05946 $</p><p>十二个半音叠加：</p><p>$ \\left(2^{\\frac{1}{12}}\\right)^{12} = 2^1 = 2 $</p><p><strong>精确还原八度，黄钟完美回归。</strong><br> 两千年的难题，在这个等式中彻底解决。</p><h3 id="_3-3-计算工具-八十一档大算盘" tabindex="-1">3.3 计算工具：八十一档大算盘 <a class="header-anchor" href="#_3-3-计算工具-八十一档大算盘" aria-label="Permalink to &quot;3.3 计算工具：八十一档大算盘&quot;">​</a></h3><p>朱载堉没有计算机，没有对数表。<br> 他用的工具，是一把<strong>八十一档大算盘</strong>。</p><blockquote><p>【原典】《朱载堉及其平均律》，戴念祖，《物理》杂志<br> 【原文】朱载堉用算盘计算了 $$ \\sqrt[12]{2} $$ 至小数点后二十五位，其精度在当时世界上是无与伦比的。<br> 【版本】戴念祖，中国科学院自然科学史研究所，《物理》1986年第15卷</p></blockquote><p>$ \\sqrt[12]{2} = 1.0594630943592952645618252\\ldots $</p><p>朱载堉将这个无理数精确计算到<strong>小数点后25位</strong>，在没有任何现代计算工具的条件下，纯粹依靠算盘与数学推理完成。</p><p>这不是偶然，这是一个人用毕生精力，在数学与音乐的交叉点上，完成的一项世界级工作。</p><h3 id="_3-4-著作体系" tabindex="-1">3.4 著作体系 <a class="header-anchor" href="#_3-4-著作体系" aria-label="Permalink to &quot;3.4 著作体系&quot;">​</a></h3><p>朱载堉的律学研究，集中于以下著作：</p><table tabindex="0"><thead><tr><th style="text-align:left;">著作</th><th style="text-align:left;">成书年份</th><th style="text-align:left;">核心内容</th></tr></thead><tbody><tr><td style="text-align:left;">《律学新说》</td><td style="text-align:left;">1584年（万历十二年）</td><td style="text-align:left;">十二平均律的首次完整数学表述</td></tr><tr><td style="text-align:left;">《律吕精义》</td><td style="text-align:left;">1596年（万历二十四年）</td><td style="text-align:left;">律学理论的全面深化与系统整理</td></tr><tr><td style="text-align:left;">《算学新说》</td><td style="text-align:left;">约同期</td><td style="text-align:left;">支撑律学计算的数学方法论</td></tr><tr><td style="text-align:left;">《乐律全书》</td><td style="text-align:left;">1606年（万历三十四年）</td><td style="text-align:left;">以上著作的合集，共四十卷</td></tr></tbody></table><h2 id="四、世界声学史的坐标-客观陈述" tabindex="-1">四、世界声学史的坐标：客观陈述 <a class="header-anchor" href="#四、世界声学史的坐标-客观陈述" aria-label="Permalink to &quot;四、世界声学史的坐标：客观陈述&quot;">​</a></h2><p>⚠️ <strong>本节立场说明：</strong><br> 以下陈述，以现有可查文献为依据，区分&quot;已确认事实&quot;与&quot;尚存争议&quot;，不夸大，不回避，只做客观中立的呈现。</p><h3 id="_4-1-时间线-各方成果的发表年份" tabindex="-1">4.1 时间线：各方成果的发表年份 <a class="header-anchor" href="#_4-1-时间线-各方成果的发表年份" aria-label="Permalink to &quot;4.1 时间线：各方成果的发表年份&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">人物</th><th style="text-align:left;">国家</th><th style="text-align:left;">成果</th><th style="text-align:left;">年份</th><th style="text-align:left;">文献依据</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>朱载堉</strong></td><td style="text-align:left;">中国（明）</td><td style="text-align:left;">《律学新说》，完整数学表述十二平均律</td><td style="text-align:left;"><strong>1584年</strong></td><td style="text-align:left;">万历十二年刊本</td></tr><tr><td style="text-align:left;">Simon Stevin</td><td style="text-align:left;">荷兰</td><td style="text-align:left;">手稿中提出十二平均律概念（未正式出版）</td><td style="text-align:left;">约1605年</td><td style="text-align:left;">荷兰皇家图书馆藏手稿</td></tr><tr><td style="text-align:left;">Marin Mersenne</td><td style="text-align:left;">法国</td><td style="text-align:left;">《和声通论》（Harmonie Universelle），系统论述十二平均律</td><td style="text-align:left;">1636年</td><td style="text-align:left;">巴黎初版本</td></tr></tbody></table><p><strong>已确认的事实：</strong><br> 朱载堉《律学新说》（1584年）的完整数学表述，早于西方已知的同类成果至少20年（Stevin约1605年），早于Mersenne的系统论述约52年。</p><h3 id="_4-2-传播路径-存疑部分的如实说明" tabindex="-1">4.2 传播路径：存疑部分的如实说明 <a class="header-anchor" href="#_4-2-传播路径-存疑部分的如实说明" aria-label="Permalink to &quot;4.2 传播路径：存疑部分的如实说明&quot;">​</a></h3><p>一个自然会被提出的问题是：<strong>西方的十二平均律研究，是否受到了朱载堉的影响？</strong></p><p><strong>如实陈述：</strong></p><ul><li>利玛窦（Matteo Ricci）于1583年抵华，与朱载堉同处明代，在华活动期间（1583—1610年）与中国学者有广泛交流。</li><li>朱载堉《律学新说》刊行于1584年，利玛窦在华期间理论上有接触可能。</li></ul><h3 id="_4-3-关于钢琴与十二平均律的关系" tabindex="-1">4.3 关于钢琴与十二平均律的关系 <a class="header-anchor" href="#_4-3-关于钢琴与十二平均律的关系" aria-label="Permalink to &quot;4.3 关于钢琴与十二平均律的关系&quot;">​</a></h3><p>⚠️ <strong>这是一个需要仔细辨析的问题。</strong></p><p><strong>事实层面：</strong></p><ul><li>现代钢琴的标准调音，采用的正是<strong>十二平均律</strong>。</li><li>钢琴（pianoforte）的发明，通常归于意大利人巴托洛梅奥·克里斯托福里（Bartolomeo Cristofori），约1700年前后在佛罗伦萨制成。</li><li>十二平均律在西方的普及，是一个从17世纪到18世纪逐步推进的过程，巴赫的《平均律钢琴曲集》（Das Wohltemperierte Clavier，1722年）是这一过程中的重要里程碑——但需注意，巴赫时代的&quot;平均律&quot;与今日严格意义上的十二平均律在调音细节上仍有学术争议。</li></ul><p><strong>需要区分的逻辑：</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>朱载堉（1584年）→ 发明了十二平均律的数学原理</span></span>
<span class="line"><span>西方（17-18世纪）→ “独立”发展了十二平均律的实践应用</span></span>
<span class="line"><span>钢琴（约1700年）→ 乐器发明，后采用十二平均律调音</span></span>
<span class="line"><span></span></span>
<span class="line"><span>三者之间：</span></span>
<span class="line"><span>✓ 朱载堉在数学原理上具有时间优先性（已确认）</span></span>
<span class="line"><span>? 朱载堉的数学是否影响了西方实践（证据不足，存疑）</span></span>
<span class="line"><span>✗ &quot;朱载堉发明了钢琴&quot;——这一说法无文献依据，不成立</span></span></code></pre></div><p><strong>客观结论：</strong><br> 朱载堉是十二平均律<strong>数学原理</strong>的最早完整表述者，这一成就本身已足够令人敬佩，无需附加未经证实的影响链条。</p><h2 id="五、两种律制的根本差异" tabindex="-1">五、两种律制的根本差异 <a class="header-anchor" href="#五、两种律制的根本差异" aria-label="Permalink to &quot;五、两种律制的根本差异&quot;">​</a></h2><p>理解了三分损益法与十二平均律，<br> 我们可以清晰地看到两者的根本差异：</p><table tabindex="0"><thead><tr><th style="text-align:left;">对比维度</th><th style="text-align:left;">三分损益法（纯律）</th><th style="text-align:left;">十二平均律</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>数学原理</strong></td><td style="text-align:left;">纯五度相生（3:2的整数比）</td><td style="text-align:left;">等比数列（$$ 2^{1/12} $$）</td></tr><tr><td style="text-align:left;"><strong>音程关系</strong></td><td style="text-align:left;">纯五度·纯四度，音程纯净</td><td style="text-align:left;">所有音程均为近似值</td></tr><tr><td style="text-align:left;"><strong>黄钟还原</strong></td><td style="text-align:left;">不能精确还原（有音差）</td><td style="text-align:left;">精确还原（数学上完美）</td></tr><tr><td style="text-align:left;"><strong>转调能力</strong></td><td style="text-align:left;">各调音色不同，转调有限制</td><td style="text-align:left;">所有调性完全等价，自由转调</td></tr><tr><td style="text-align:left;"><strong>哲学背景</strong></td><td style="text-align:left;">顺应天地自然之数（整数比）</td><td style="text-align:left;">数学理性的人工等分</td></tr><tr><td style="text-align:left;"><strong>代表应用</strong></td><td style="text-align:left;">中国传统雅乐·古琴</td><td style="text-align:left;">现代钢琴·管弦乐</td></tr></tbody></table><p><strong>一个深刻的对立：</strong><br> 三分损益法，是先人试图用<strong>自然整数比</strong>来描述天地之音——它的&quot;不完美&quot;（黄钟不能还原），恰恰是自然之数无法被人工完全驯服的体现。</p><p>十二平均律，是用<strong>数学理性</strong>强行等分八度——它的&quot;完美&quot;（精确还原），是以牺牲每个音程的纯净度为代价的。</p><p>两者之间，没有高下之分，只有哲学取向的不同：<strong>一个顺应自然，一个驾驭自然。</strong></p><h2 id="六、数学结构-通向纳音五行的桥梁" tabindex="-1">六、数学结构：通向纳音五行的桥梁 <a class="header-anchor" href="#六、数学结构-通向纳音五行的桥梁" aria-label="Permalink to &quot;六、数学结构：通向纳音五行的桥梁&quot;">​</a></h2><p>本篇作为主干19·纳音五行的前置深化篇，<br> 最后回到那个关键的数学结构：</p><h3 id="_6-1-旋相为宫-12-×-5-60" tabindex="-1">6.1 旋相为宫：12 × 5 = 60 <a class="header-anchor" href="#_6-1-旋相为宫-12-×-5-60" aria-label="Permalink to &quot;6.1 旋相为宫：12 × 5 = 60&quot;">​</a></h3><p>【原典】《三命通会·总论纳音》<br> 【原文】尝观《笔谈》论六十甲子纳音，本六十律，旋相为宫法也。一律含五音，凡气始于东方而右行，音起于西方而左行，阴阳相错而生变化。<br> 【版本】明·万民英撰，《钦定四库全书》本</p><p>十二律，每律各可作为&quot;宫音&quot;（主音）起点，<br> 展开完整五音音阶：</p><p>$ 12 \\text{（律）} \\times 5 \\text{（音）} = 60 \\text{（独立音律位置）} $</p><p>这60个音律位置，与六十甲子一一对应，构成纳音五行的完整数学基础。</p><h3 id="_6-2-气与音的相反方向-深化" tabindex="-1">6.2 气与音的相反方向（深化） <a class="header-anchor" href="#_6-2-气与音的相反方向-深化" aria-label="Permalink to &quot;6.2 气与音的相反方向（深化）&quot;">​</a></h3><p>主干18已提及气与音方向相反，这里做数学层面的深化说明：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>五行之气（顺时针·右行）：</span></span>
<span class="line"><span>木（东）→ 火（南）→ 土（中）→ 金（西）→ 水（北）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>五行之音（逆时针·左行）：</span></span>
<span class="line"><span>金（商）→ 火（徵）→ 木（角）→ 水（羽）→ 土（宫）</span></span></code></pre></div><p>正是这种<strong>方向的相反</strong>，<br> 使得60个音律位置不是简单的5×12重复，<br> 而是产生了60种各不相同的阴阳五行组合——<br> 这是纳音五行能够为六十甲子每对干支赋予独特五行属性的数学根源。</p><p><strong>如果气与音方向相同，只会产生12种重复；正因相反，才产生了60种变化。</strong><br> 这是先人在数学结构设计上的深刻洞见。</p><h2 id="七、现代视角-朱载堉的意义" tabindex="-1">七、现代视角：朱载堉的意义 <a class="header-anchor" href="#七、现代视角-朱载堉的意义" aria-label="Permalink to &quot;七、现代视角：朱载堉的意义&quot;">​</a></h2><p>朱载堉的成就，在今天值得被重新认识，原因有三：</p><p><strong>① 数学成就本身</strong><br> 在没有计算机、没有对数表的条件下，<br> 精确计算 $$ \\sqrt[12]{2} $$ 至25位小数， 这是纯粹的数学能力与意志力的体现。 $</p><p><strong>② 跨学科整合</strong><br> 朱载堉将音乐、数学、天文、历法融为一体，他的律学研究，本质上是对先人&quot;律历合一&quot;传统的最高水平的数学实现。<br> 他不是在&quot;发明新东西&quot;，而是在<strong>将两千年的传统推向极致</strong>。</p><p><strong>③ 人格的力量</strong><br> 一个放弃王位、席藁独处十九年、用毕生精力研究音律数学的人——他的成就，不只是数学的，也是人格的。 《明史》对他的记载，是对一种生命选择的尊重。</p><p>【原典】《明史·乐志》<br> 【原文】载堉……上历算岁差之法，及所著乐律书，考辨详确，识者称之。<br> 【版本】清·张廷玉等撰，中华书局点校本（二十四史）</p><p>&quot;考辨详确，识者称之&quot;——严谨考证，知者称赞。<br> 这八个字，是《明史》给朱载堉最简洁也最准确的评价。</p><h2 id="八、跨体系接口" tabindex="-1">八、跨体系接口 <a class="header-anchor" href="#八、跨体系接口" aria-label="Permalink to &quot;八、跨体系接口&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">体系</th><th style="text-align:left;">本篇的作用</th><th style="text-align:left;">具体说明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>主干18·五音六律</strong></td><td style="text-align:left;">直接前置</td><td style="text-align:left;">本篇为主干18的深化扩展，概念基础见主干18</td></tr><tr><td style="text-align:left;"><strong>主干19·纳音五行</strong></td><td style="text-align:left;">直接后续</td><td style="text-align:left;">12×5=60的数学结构，是纳音五行的底层逻辑</td></tr><tr><td style="text-align:left;"><strong>主干13·六十甲子</strong></td><td style="text-align:left;">对应结构</td><td style="text-align:left;">60个音律位置与六十甲子一一对应</td></tr><tr><td style="text-align:left;"><strong>主干14·二十四节气</strong></td><td style="text-align:left;">时间验证</td><td style="text-align:left;">十二律与十二月对应；候气法以律管验证节气</td></tr><tr><td style="text-align:left;"><strong>主干15·历法体系</strong></td><td style="text-align:left;">数理同源</td><td style="text-align:left;">律历合一；律数即历数</td></tr><tr><td style="text-align:left;"><strong>Jing·黄帝内经</strong></td><td style="text-align:left;">医学应用</td><td style="text-align:left;">五音对应五脏；五音疗愈的数理基础</td></tr></tbody></table><h2 id="九、本章小结" tabindex="-1">九、本章小结 <a class="header-anchor" href="#九、本章小结" aria-label="Permalink to &quot;九、本章小结&quot;">​</a></h2><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>律数精解 · 四句话总结：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 三分损益法的数学本质：</span></span>
<span class="line"><span>   纯五度相生律，从黄钟（81）出发，</span></span>
<span class="line"><span>   ×2/3（损）与×4/3（益）交替推算十二律；</span></span>
<span class="line"><span>   &quot;黄钟不能还原&quot;（音差≈1.01364）是其数学局限，</span></span>
<span class="line"><span>   先人早已发现，持续探索近两千年。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. 朱载堉的解决方案：</span></span>
<span class="line"><span>   以 $$\\sqrt[12]{2}$$ 精确等分八度，</span></span>
<span class="line"><span>   发明十二平均律（&quot;新法密率&quot;），</span></span>
<span class="line"><span>   1584年《律学新说》完整表述，</span></span>
<span class="line"><span>   用算盘计算至小数点后25位。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. 世界声学史坐标：</span></span>
<span class="line"><span>   朱载堉（1584年）早于西方已知同类成果至少20年；</span></span>
<span class="line"><span>   中西之间是否存在知识传播，目前证据不足，</span></span>
<span class="line"><span>   以客观中立态度如实陈述，不作未经证实的推断。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>4. 通向纳音五行：</span></span>
<span class="line"><span>   12律 × 5音 = 60，对应六十甲子；</span></span>
<span class="line"><span>   气与音方向相反，产生60种独立变化——</span></span>
<span class="line"><span>   这是纳音五行的完整数学根源。</span></span></code></pre></div><hr><h2 id="引用来源" tabindex="-1">引用来源 <a class="header-anchor" href="#引用来源" aria-label="Permalink to &quot;引用来源&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">编号</th><th style="text-align:left;">来源</th><th style="text-align:left;">核心内容</th></tr></thead><tbody><tr><td style="text-align:left;">1</td><td style="text-align:left;">《汉书·律历志》，东汉·班固撰，中华书局点校本</td><td style="text-align:left;">&quot;竟不能合&quot;——黄钟不能还原问题的最早官方记载；三分损益法的历史局限</td></tr><tr><td style="text-align:left;">2</td><td style="text-align:left;">《管子·地员篇》，战国（存疑，今本为后人整理）</td><td style="text-align:left;">三分损益法原文；黄钟基准81的来源（&quot;四开以合九九&quot;）</td></tr><tr><td style="text-align:left;">3</td><td style="text-align:left;">《明史·乐志》，清·张廷玉等撰，中华书局点校本（二十四史）</td><td style="text-align:left;">朱载堉生平；辞让王位；&quot;考辨详确，识者称之&quot;</td></tr><tr><td style="text-align:left;">4</td><td style="text-align:left;">戴念祖，《朱载堉及其平均律》，《物理》1986年第15卷，中国科学院自然科学史研究所</td><td style="text-align:left;">朱载堉算盘计算至25位小数；世界声学史地位的学术评价</td></tr><tr><td style="text-align:left;">5</td><td style="text-align:left;">朱载堉《律学新说》，万历十二年（1584年）刊本</td><td style="text-align:left;">十二平均律首次完整数学表述原文（&quot;置一尺为实，以密率除之，凡十二遍&quot;）</td></tr><tr><td style="text-align:left;">6</td><td style="text-align:left;">《三命通会·总论纳音》，明·万民英撰，《钦定四库全书》本</td><td style="text-align:left;">旋相为宫；12×5=60；气与音的相反方向</td></tr><tr><td style="text-align:left;">7</td><td style="text-align:left;">知乎·大老李，《国际上是否承认十二平均律是中国人发明的？》，参考多方学术来源</td><td style="text-align:left;">利玛窦传播路径的存疑说明；西方同期研究的时间线对比</td></tr></tbody></table><hr><p><strong>前置篇：</strong> 主干18·五音六律<br><strong>后续篇：</strong> 主干19·纳音五行</p>`,119)])])}const h=e(s,[["render",r]]);export{x as __pageData,h as default};
